6858	// first). O-side split: MMA acquires o_empty (correction rescaled O) before each PV.
6859	struct BarsFA4 { uint64_t kf_full[FA4KVS], vf_full[FA4KVS], kv_empty[FA4KVS], s_full[2], p_full[2], o_full[2], o_empty[2], c_full[4], c_empty[4], q_full[1], q_empty[1], q_tma[1], q_sched[1], ord[2]; }; // D4: c_full/c_empty are [half*2+slot] depth-2
